<?php
$units=$pdo->query('SELECT id,unit_code FROM units ORDER BY unit_code')->fetchAll();
$docs=$pdo->query("SELECT d.*,u.unit_code,us.name uploader FROM unit_documents d LEFT JOIN units u ON u.id=d.unit_id JOIN users us ON us.id=d.uploaded_by ORDER BY d.created_at DESC LIMIT 100")->fetchAll();
?>
<?php if(can('documents.upload')): ?><div class="card panel"><h3>Upload Foto Kerusakan / Quotation / Purchase Order</h3><form method="post" action="actions/upload_document.php" enctype="multipart/form-data" class="form-grid compact"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><label>Unit<select name="unit_id"><option value="">Umum</option><?php foreach($units as $u):?><option value="<?=$u['id']?>"><?=e($u['unit_code'])?></option><?php endforeach;?></select></label><label>Jenis Dokumen<select name="document_type"><?php foreach(['Foto Kerusakan','Quotation','Purchase Order','Invoice','BAST','Lainnya'] as $t):?><option><?=e($t)?></option><?php endforeach;?></select></label><label>File<input type="file" name="document" accept="image/*,.pdf" required></label><label>Catatan<input name="notes"></label><button class="btn primary">Upload</button></form></div><?php endif; ?>
<div class="card panel"><h3>Arsip Dokumen</h3><table><thead><tr><th>Tanggal</th><th>Unit</th><th>Jenis</th><th>File</th><th>Uploader</th><th>Catatan</th></tr></thead><tbody><?php foreach($docs as $d):?><tr><td><?=e($d['created_at'])?></td><td><?=e($d['unit_code']??'-')?></td><td><span class="status st-blue"><?=e($d['document_type'])?></span></td><td><a target="_blank" href="<?=e($d['file_path'])?>"><?=e($d['original_name'])?></a></td><td><?=e($d['uploader'])?></td><td><?=e($d['notes'])?></td></tr><?php endforeach;?></tbody></table></div>
